"{0} {1}px Inter, \"Segoe UI\", Arial, sans-serif": "{0} {1}px Inter, \"Segoe UI\", Arial, sans-serif",
"Claude Sonnet 5.5 – schnell & günstig (Standard)": "Claude Sonnet 5.5 – швидкий і недорогий (стандарт)",
"Claude Opus 5.5 – genauer bei schwierigen Plänen": "Claude Opus 5.5 – точніший для складних планів",
"Claude Haiku 5.5 – sehr günstig, einfache Aufgaben": "Claude Haiku 5.5 – дуже недорогий, прості завдання",
"Kein API-Schlüssel hinterlegt – KI-Einstellungen öffnen.": "API-ключ не збережено – відкрийте налаштування ШІ.",
"Keine Verbindung zur KI (Internet/Firewall?).": "Немає з'єднання з ШІ (інтернет/брандмауер?).",
"API-Schlüssel ungültig oder gelöscht. Neuen Schlüssel in der Claude Console anlegen.": "API-ключ недійсний або видалений. Створіть новий ключ у Claude Console.",
"Kein Guthaben auf dem Anthropic-Konto. Unter „Abrechnung“ in der Claude Console Guthaben aufladen.": "На рахунку Anthropic немає коштів. Поповніть баланс у Claude Console в розділі «Оплата».",
"Zu viele Anfragen in kurzer Zeit – bitte kurz warten.": "Забагато запитів за короткий час – зачекайте трохи.",
"Die KI ist gerade überlastet – bitte gleich nochmal versuchen.": "ШІ зараз перевантажений – спробуйте ще раз за мить.",
"KI-Fehler {0}: {1}": "Помилка ШІ {0}: {1}",
"KI arbeitet … ": "ШІ працює … ",
"Google (Gemini) – Schlüssel aus der Master-App (Standard)": "Google (Gemini) – ключ із Master-додатка (стандарт)",
"Claude (Anthropic) – eigener Schlüssel nötig": "Claude (Anthropic) – потрібен власний ключ",
"sk-ant-…": "sk-ant-…",
"Nur falls Claude gewählt: Claude-Schlüssel und Modell": "Лише якщо вибрано Claude: ключ і модель Claude",
