"Google, ": "Google, ",
"Claude": "Claude",
"Verbindung steht ✓ ({0} – Antwort: {1})": "З'єднання встановлено ✓ ({0} – відповідь: {1})",
"Speichern & Verbindung testen": "Зберегти й перевірити з'єднання",
"Zugang zur KI": "Доступ до ШІ",
"KI-Anbieter": "Постачальник ШІ",
"Mit Google ist nichts einzutragen: TW-CAD nimmt automatisch den Schlüssel aus der Master-App (gleicher Browser). Abgerechnet wird über dein Google-Konto.": "З Google нічого вводити не потрібно: TW-CAD автоматично бере ключ із Master-додатка (той самий браузер). Оплата – через ваш обліковий запис Google.",
"z. B.: Bad 2,80 × 2,20 m Innenmaß, Wände 11,5 cm, Tür 88,5 unten links mit 15 cm Abstand, Fenster 101 rechts mittig BRH 1,50, Boden 60×30 Drittelverband, Wand 30×60 bis 2,10 m": "напр.: Ванна 2,80 × 2,20 м внутрішній розмір, стіни 11,5 см, двері 88,5 внизу ліворуч, 15 см від кута, вікно 101 праворуч по центру, підвіконня 1,50, підлога 60×30 зі зміщенням на третину, стіна 30×60 до 2,10 м",
"Zeichnen per Text": "Креслення текстом",
"Plan ändern per Sprache oder Text": "Змінити план голосом або текстом",
"Sag einfach, was geändert werden soll: „Fenster im Bad 1,01 breiter“, „Wand zwischen Küche und Flur 2 cm dicker“, „WC im Gäste-WC an die Nordwand“, „Boden im Flur 60 × 60 Kreuzfuge“ oder frag „wie groß ist das Bad?“. Mit Mikrofon-Knopf auch gesprochen. Kurzbefehl überall: Strg+K.": "Просто скажіть, що змінити: «вікно у ванній ширше на 1,01», «стіна між кухнею та коридором товща на 2 см», «унітаз у гостьовому туалеті до північної стіни», «підлога в коридорі 60 × 60 прямий шов» або запитайте «яка площа ванної?». Кнопкою мікрофона – голосом. Скорочення: Ctrl+K.",
"Grundriss aus Raumprogramm entwerfen": "Спроєктувати план за програмою приміщень",
"Raumprogramm beschreiben (Räume, Größen, Geschosse, Grundstück) – die KI entwirft einen DIN-gerechten Grundriss und TW-CAD baut ihn als neues Projekt mit Wänden, Räumen, Türen, Fenstern, Treppe und Dach auf.": "Опишіть програму приміщень (кімнати, розміри, поверхи, ділянка) – ШІ спроєктує план за нормами DIN, а TW-CAD створить новий проєкт зі стінами, кімнатами, дверима, вікнами, сходами й дахом.",
"Visualisierung": "Візуалізація",
"In „3D & Fassade“ (oder „Raum von innen“) rechts unter Export: „KI-Visualisierung“ – die KI schreibt aus dem 3D-Bild fertige Prompts für Bild-KIs (ChatGPT, Firefly, Midjourney) plus Referenzbild und Kundentext.": "У «3D і фасад» (або «Приміщення зсередини») праворуч у розділі Експорт: «ШІ-візуалізація» – ШІ з 3D-зображення пише готові промпти для графічних ШІ (ChatGPT, Firefly, Midjourney), а також еталонне зображення й текст для клієнта.",
"Leistungsverzeichnis auswerten": "Обробити відомість робіт",
"LV als PDF, GAEB (X83/D83) oder Text: die KI findet alle Fliesenpositionen mit Hersteller, Serie, Format, Farbe und Fuge und legt sie in der Fliesen-Bibliothek dieses Projekts an. Danach im Fliesenplan „Aus LV/Bibliothek“.": "Відомість робіт як PDF, GAEB (X83/D83) або текст: ШІ знаходить усі позиції плитки з виробником, серією, форматом, кольором і швом та додає їх до бібліотеки плитки цього проєкту. Потім у плані плитки «З відомості/бібліотеки».",
"{0} Fliesen in der Bibliothek": "{0} плиток у бібліотеці",
"Plan lesen": "Прочитати план",
"Über „Plan importieren“ (Symbol oben) eine Datei laden – dort gibt es den Knopf „KI: Plan lesen“.": "Завантажте файл через «Імпорт плану» (значок угорі) – там є кнопка «ШІ: прочитати план».",
"KI-Assistent": "ШІ-помічник",
"Beschreibung wird umgesetzt": "Опис виконується",
"KI: Zeichnen": "ШІ: креслення",
"Raum": "Приміщення",
"Bodenfliese": "Підлогова плитка",
"Wandfliese": "Настінна плитка",
"KI: {0} Schritte ausgeführt – bitte prüfen.": "ШІ: виконано кроків – {0}, будь ласка, перевірте.",
".pdf,.x83,.d83,.x84,.xml,.txt,.gaeb,application/pdf": ".pdf,.x83,.d83,.x84,.xml,.txt,.gaeb,application/pdf",
"LV wird gelesen": "Відомість робіт зчитується",
"Bitte alle Fliesenpositionen aus diesem LV auslesen.": "Bitte alle Fliesenpositionen aus diesem LV auslesen.",
