"Fliesen aus LV": "Плитка з відомості",
"Fliese": "Плитка",
"{0} Fliesenpositionen aus dem LV übernommen ✓": "Перенесено позицій плитки з відомості: {0} ✓",
"Fliese im Internet suchen": "Шукати плитку в інтернеті",
"Suchbegriff (Hersteller, Serie, Farbe, Format)": "Пошуковий запит (виробник, серія, колір, формат)",
"sucht „": "шукає «",
"Fliese aus Internet": "Плитка з інтернету",
"Fliesenbild": "Зображення плитки",
"Gefunden: {0} {1} – Produktbild übernommen ✓": "Знайдено: {0} {1} – зображення товару перенесено ✓",
"Gefunden: {0} {1} – Farbe/Optik übernommen (Bild darf vom Hersteller nicht direkt geladen werden – eigenes Foto über „Foto hochladen“ möglich).": "Знайдено: {0} {1} – колір/вигляд перенесено (зображення не можна завантажити безпосередньо з сайту виробника – своє фото можна додати через «Завантажити фото»).",
