"Projekt": "Проєкт",
"Bedienstufe – Einstieg: nur das Nötigste (Raum zeichnen, Fliesen planen, fertig) · Profi: das volle CAD. Wird gemerkt, Projekte bleiben in beiden Stufen vollständig.": "Рівень – Базовий: лише найнеобхідніше (накреслити приміщення, спланувати плитку, готово) · Профі: повний CAD. Вибір запам'ятовується, проєкти залишаються повними в обох режимах.",
"TW-CAD als App auf diesem Gerät installieren (Startmenü/Desktop bzw. Home-Bildschirm, funktioniert dann auch offline)": "Встановити TW-CAD як застосунок на цей пристрій (меню «Пуск»/робочий стіл або головний екран, тоді працює й офлайн)",
"Neuer Plan – leeres Blatt (der jetzige Plan wird vorher gespeichert oder verworfen, du wirst gefragt)": "Новий план – чистий аркуш (поточний план буде збережено або відкинуто, вас запитають)",
"Löschen (Entf) – mit Auswahl: Auswahl löschen · ohne Auswahl: Lösch-Modus, dann Elemente anklicken · Strg+Z holt alles zurück": "Видалити (Del) – з виділенням: видалити виділене · без виділення: режим видалення, потім клацайте елементи · Ctrl+Z усе повертає",
"Projekte öffnen / neu": "Відкрити / новий проєкт",
