"Bezugsmaßstab der Zeichnung – bestimmt Schrift-, Maß- und Liniengrößen und den Plandruck (wie in ArchiCAD/Allplan). Gezeichnet wird immer in echten Maßen.": "Базовий масштаб креслення – визначає розмір тексту, розмірів, ліній і друк плану (як в ArchiCAD/Allplan). Креслимо завжди в реальних розмірах.",
