"Löschen: im Grundriss oder Lageplan das Element anklicken und dann Löschen drücken.": "Видалити: клацніть елемент на плані поверху або ситуаційному плані, потім натисніть «Видалити».",
"Lösch-Modus: Elemente anklicken – Esc oder nochmal „Löschen“ beendet": "Режим видалення: клацайте елементи – Esc або ще раз «Видалити» завершує",
