"Das Werkzeug-Fenster wurde blockiert. Bitte Pop-ups für diese Seite erlauben (Symbol rechts in der Adressleiste) und nochmal klicken.": "Вікно інструментів заблоковано. Дозвольте спливаючі вікна для цієї сторінки (значок праворуч в адресному рядку) і клацніть ще раз.",
"Werkzeuge im eigenen Fenster · F11 = Zeichnung im Vollbild": "Інструменти в окремому вікні · F11 = креслення на весь екран",
"Alles wieder in einem Fenster": "Усе знову в одному вікні",
"Vollbild nicht möglich – F11 drücken": "Повноекранний режим недоступний – натисніть F11",
