"📋 LV-Text einfügen (ohne KI)": "📋 Вставити текст відомості (без ШІ)",
"⚡ Alle Räume automatisch belegen": "⚡ Автоматично заповнити всі приміщення",
"Noch keine Fliesen aus einem Leistungsverzeichnis. Kopiere den LV-Text (aus PDF oder GAEB als Text) über „LV-Text einfügen“ hinein – Positionen mit Format, Hersteller, Farbe, Rutschhemmung und Bereich (Boden/Wand/Sockel) werden erkannt.": "Ще немає плитки з відомості. Вставте текст відомості (з PDF або GAEB як текст) через «Вставити текст відомості» – буде розпізнано позиції з форматом, виробником, кольором, протиковзкістю й зоною (підлога/стіна/плінтус).",
"Noch keine Fliesen aus dem LV. Wege: LV-Datei (PDF/GAEB) von der KI lesen lassen, direkt aus dem Baustellen-Ordner holen oder den LV-Text hineinkopieren – die Fliesenpositionen mit Format, Hersteller, Farbe, Rutschhemmung und Bereich (Boden/Wand/Sockel) werden erkannt.": "Ще немає плитки з відомості. Способи: дати ШІ прочитати файл відомості (PDF/GAEB), узяти його з папки об'єкта або вставити текст – позиції плитки з форматом, виробником, кольором, протиковзкістю й зоною (підлога/стіна/плінтус) буде розпізнано.",
"Antippen = für „": "Торкніться = для «",
"“ übernehmen. „Automatisch belegen“: Boden ← Bodenfliese, Wände ← Wandfliese, Sockel ← Sockelposition; passt der Raumname zu einer Position (z. B. „Bad“), wird diese genommen.": "». «Заповнити автоматично»: підлога ← плитка підлоги, стіни ← настінна плитка, плінтус ← позиція плінтуса; якщо назва приміщення збігається з позицією (напр. «Ванна»), береться вона.",
"Antippen = für „{0}“ übernehmen. „Automatisch belegen“: Boden ← Bodenfliese, Wände ← Wandfliese, Sockel ← Sockelposition; passt der Raumname zu einer Position (z. B. „Bad“), wird diese genommen.": "Торкніться = застосувати до «{0}». «Заповнити автоматично»: підлога ← плитка підлоги, стіни ← настінна плитка, плінтус ← позиція плінтуса; якщо назва приміщення збігається з позицією (напр. «Ванна»), береться вона.",
