"Haken setzen oder in der Mitte eine Fliese antippen. Ohne eigene Fliese wird die Wandfliese verwendet. Die Wand dahinter wird bis zur Bauteilhöhe automatisch abgezogen.": "Поставте позначку або торкніться плитки посередині. Без окремої плитки береться настінна. Стіна позаду автоматично віднімається до висоти елемента.",
