"Treppe passt nicht in „{0}“ ({1} × {2} m) – bitte mit dem Treppen-Werkzeug einsetzen (z. B. gewendelt).": "Сходи не вміщаються в «{0}» ({1} × {2} м) – вставте інструментом «Сходи» (напр. із забіжними).",
"z. B.: Einfamilienhaus für 4 Personen, ca. 140 m² Wohnfläche, 2 Geschosse mit Satteldach 38°.\nEG: Diele mit Garderobe, Gäste-WC, Küche offen zu Essen/Wohnen ca. 40 m² nach Süden, Hauswirtschaftsraum, Arbeitszimmer 10 m².\nOG: Eltern 15 m² mit Ankleide, 2 Kinderzimmer je 12 m², Bad 10 m² mit bodengleicher Dusche und Wanne, Abstellraum.\nGrundstück: Haus max. 11 × 9 m, Zufahrt von Westen.": "напр.: приватний будинок для 4 осіб, бл. 140 м² житлової площі, 2 поверхи з двосхилим дахом 38°.\n1-й поверх: передпокій із гардеробом, гостьовий WC, кухня, відкрита до їдальні/вітальні бл. 40 м² на південь, господарська кімната, кабінет 10 м².\n2-й поверх: батьки 15 м² з гардеробною, 2 дитячі по 12 м², ванна 10 м² з душем урівень із підлогою та ванною, комора.\nДілянка: будинок макс. 11 × 9 м, заїзд із заходу.",
"Die KI entwirft einen Grundriss als Vorschlag (Achsmaße, Raster 12,5 cm) und TW-CAD baut ihn als neues Projekt mit Wänden, Räumen, Türen, Fenstern, Treppe und Dach auf. Danach normal weiterbearbeiten – nichts im aktuellen Projekt wird überschrieben.": "ШІ пропонує план (осьові розміри, сітка 12,5 см), а TW-CAD будує з нього новий проєкт зі стінами, приміщеннями, дверима, вікнами, сходами й дахом. Далі редагуйте як завжди – поточний проєкт не перезаписується.",
