"NRF gesamt (inkl. Außenflächen)": "NRF разом (із зовнішніми площами)",
"Raumliste": "Список приміщень",
"Flächen sind Netto-Raumflächen aus dem Modell (Innenmaß der Wände, ohne Putzabzug). Wohnfläche nach Wohnflächenverordnung (WoFlV): Raumteile ab 2 m lichter Höhe voll, 1–2 m zur Hälfte, unter 1 m nicht; Balkone/Terrassen in der Regel zu einem Viertel; Keller, Heizungsräume und Garagen zählen nicht zur Wohnfläche. BGF = Brutto-Grundfläche (Außenmaß), KGF = BGF − NRF, BRI ≈ BGF × Geschosshöhe.": "Площі – чисті площі приміщень із моделі (внутрішній розмір стін, без вирахування тиньку). Житлова площа за німецьким положенням WoFlV: частини приміщень із висотою в світлі від 2 м – повністю, 1–2 м – наполовину, нижче 1 м – не враховуються; балкони/тераси зазвичай на чверть; підвали, котельні й гаражі до житлової площі не входять. BGF = загальна площа брутто (за зовнішнім розміром), KGF = площа конструкцій = BGF − NRF (чиста площа), BRI ≈ BGF × висота поверху (будівельний об'єм).",
"Raumbuch – Flächen nach DIN 277 und WoFlV": "Відомість приміщень – площі за DIN 277 і WoFlV",
"{0} Räume · Flächen live aus dem Grundriss · Zeile anklicken = im Plan zeigen": "Приміщень: {0} · площі наживо з плану · клацніть рядок = показати на плані",
