"Noch keine Räume. Im Grundriss mit dem Werkzeug „Raum“ (R) in die Räume klicken – dann erscheinen sie hier automatisch.": "Ще немає приміщень. На плані клацніть інструментом «Приміщення» (R) у приміщення – тоді вони з'являться тут автоматично.",
