"keine Wohnfläche": "не житлова площа",
"aus dem Raumnamen vorgeschlagen": "запропоновано за назвою приміщення",
"Vorschlag": "Пропозиція",
"Je Geschoss": "За поверхами",
"Nutzung wird aus dem Raumnamen vorgeschlagen (Bad → NUF 7, Flur → VF, Heizung → TF …) und lässt sich je Raum ändern. Dachschrägen werden aus dem Dach berechnet: Wohnfläche ≥ 2 m voll, 1–2 m halb, unter 1 m nicht (§ 4 WoFlV).": "Призначення пропонується за назвою приміщення (Ванна → NUF 7, Коридор → VF, Котельня → TF …) і змінюється для кожного приміщення. Скоси розраховуються з даху: житлова площа ≥ 2 м повністю, 1–2 м наполовину, нижче 1 м не враховується (§ 4 WoFlV).",
