"Regelwerk: {0} · Barrierefreiheit: {1} · {2} Fehler, {3} Hinweise, {4} erfüllt. Vereinfachte Prüfung aus dem CAD-Modell – ersetzt keine bauaufsichtliche Prüfung.": "Норми: {0} · безбар'єрність: {1} · помилок {2}, приміток {3}, виконано {4}. Спрощена перевірка з CAD-моделі – не замінює офіційної перевірки будівельним наглядом.",
"KI-Erläuterung": "Пояснення ШІ",
"Raumhöhen, Belichtung, Türen, Treppen (DIN 18065), Absturzsicherung, Bewegungsflächen (DIN 18040-2) – Zeile anklicken = im Plan zeigen": "Висота приміщень, освітлення, двері, сходи (DIN 18065), захист від падіння, площі маневрування (DIN 18040-2) – клацніть рядок = показати на плані",
"Bauordnung ": "Будівельний кодекс ",
"Barrierefreiheit ": "Безбар'єрність ",
"🤖 KI-Erläuterung": "🤖 Пояснення ШІ",
"schließen": "закрити",
"Keine Einträge in dieser Auswahl.": "У цьому виборі немає записів.",
"Noch nichts zu prüfen – zeichne Wände, Räume, Türen und Fenster.": "Ще нема чого перевіряти – накресліть стіни, приміщення, двері й вікна.",
"Vereinfachte Prüfung aus dem Modell nach {0}, DIN 18065 und DIN 18040-2. Sie ersetzt keine bauaufsichtliche Prüfung; im Zweifel gilt der Normtext bzw. die Landesbauordnung. Räume ohne Aufenthalt (Bad, Flur, Abstellraum …) werden bei Raumhöhe und Belichtung nicht geprüft – die Nutzung stellst du im Raumbuch ein.": "Спрощена перевірка з моделі за {0}, DIN 18065 (сходи) і DIN 18040-2 (безбар'єрне житло). Вона не замінює офіційної перевірки; у разі сумніву діє текст норми або будівельний кодекс землі. Нежитлові приміщення (ванна, коридор, комора …) за висотою й освітленням не перевіряються – призначення задається у відомості приміщень.",
"Erst KI einrichten (Stern-Knopf oben) – dann erklärt sie die Prüfung.": "Спершу налаштуйте ШІ (кнопка із зіркою вгорі) – тоді він пояснить перевірку.",
"Alles erfüllt – die Prüfung hat keine Fehler oder Hinweise gefunden. 👍": "Усе виконано – перевірка не знайшла помилок чи приміток. 👍",
"KI denkt nach …": "ШІ думає …",
