"So geht’s: Lageplan als PDF über „Plan importieren“ hinterlegen (Ziel: Lageplan), maßstäblich einstellen. Dann Grundstücksgrenze, Nachbargebäude und möglichst viele Höhenpunkte aus dem Plan eintragen. Das 3D-Gelände entsteht automatisch – Ansicht „3D & Fassade“.": "Як це працює: покладіть генплан як PDF через «Імпорт плану» (ціль: генплан) і задайте масштаб. Потім внесіть межу ділянки, сусідні будівлі та якомога більше висотних позначок із плану. 3D-рельєф створюється автоматично – вигляд «3D і фасад».",
